// Layered, synthesized archery Foley. No external samples or downloads.
export class ArcheryAudio {
 constructor(){this.enabled=true;this.context=null;this.flight=null;}
 unlock(){if(!this.enabled)return false;try{if(!this.context){const Audio=globalThis.AudioContext||globalThis.webkitAudioContext;if(!Audio)return false;this.context=new Audio();const c=this.context;this.master=c.createGain();this.master.gain.value=.65;const limiter=c.createDynamicsCompressor();limiter.threshold.value=-12;limiter.knee.value=12;limiter.ratio.value=5;limiter.attack.value=.003;limiter.release.value=.18;this.master.connect(limiter).connect(c.destination);this.noise=c.createBuffer(1,c.sampleRate*2,c.sampleRate);const data=this.noise.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;}if(this.context.state==='suspended')this.context.resume().catch(()=>{});return true;}catch{return false;}}
 setEnabled(enabled){this.enabled=enabled;if(!enabled)this.stopFlight();if(this.context)this.master.gain.setTargetAtTime(enabled?.65:0,this.context.currentTime,.025);if(enabled)this.unlock();}
 noiseBurst({duration=.2,volume=.3,frequency=1000,endFrequency=frequency,type='bandpass',delay=0,q=.7}){if(!this.enabled||!this.unlock())return;const c=this.context,t=c.currentTime+delay,source=c.createBufferSource(),filter=c.createBiquadFilter(),gain=c.createGain();source.buffer=this.noise;filter.type=type;filter.Q.value=q;filter.frequency.setValueAtTime(frequency,t);filter.frequency.exponentialRampToValueAtTime(Math.max(30,endFrequency),t+duration);gain.gain.setValueAtTime(.0001,t);gain.gain.exponentialRampToValueAtTime(volume,t+.004);gain.gain.exponentialRampToValueAtTime(.0001,t+duration);source.connect(filter).connect(gain).connect(this.master);source.start(t);source.stop(t+duration+.02);source.onended=()=>{source.disconnect();filter.disconnect();gain.disconnect();};}
 body({frequency=120,endFrequency=55,duration=.25,volume=.4,delay=0,type='sine'}){if(!this.enabled||!this.unlock())return;const c=this.context,t=c.currentTime+delay,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(frequency,t);o.frequency.exponentialRampToValueAtTime(endFrequency,t+duration);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(volume,t+.003);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g).connect(this.master);o.start(t);o.stop(t+duration+.02);o.onended=()=>{o.disconnect();g.disconnect();};}
 draw(){this.noiseBurst({duration:.23,volume:.045,frequency:650,endFrequency:220,q:3});}
 release(power=1){this.body({frequency:210+power*70,endFrequency:85,duration:.16,volume:.18,type:'triangle'});this.noiseBurst({duration:.10,volume:.09,frequency:1400,endFrequency:450});this.noiseBurst({duration:.20,volume:.065,frequency:1050,endFrequency:350,delay:.025});this.startFlight();}
 startFlight(){this.stopFlight();if(!this.enabled||!this.unlock())return;const c=this.context,source=c.createBufferSource(),filter=c.createBiquadFilter(),gain=c.createGain(),pan=c.createStereoPanner(),muffle=c.createBiquadFilter();muffle.type='lowpass';muffle.frequency.value=1100;source.buffer=this.noise;source.loop=true;filter.type='bandpass';filter.frequency.value=700;filter.Q.value=.8;gain.gain.setValueAtTime(0,c.currentTime);gain.gain.linearRampToValueAtTime(.025,c.currentTime+.06);source.connect(filter).connect(muffle).connect(gain).connect(pan).connect(this.master);source.start();this.flight={source,filter,muffle,gain,pan,startedAt:c.currentTime};source.onended=()=>{source.disconnect();filter.disconnect();muffle.disconnect();gain.disconnect();pan.disconnect();};}
 updateFlight(progress,speed,wind){if(!this.flight||!this.enabled)return;const t=this.context.currentTime,p=Math.max(0,Math.min(1,progress));this.flight.filter.frequency.setTargetAtTime(450+Math.min(100,speed)*4+p*150,t,.06);this.flight.gain.gain.setTargetAtTime(.025*Math.exp(-Math.max(0,t-this.flight.startedAt)*5),t,.05);this.flight.pan.pan.setTargetAtTime(Math.max(-.65,Math.min(.65,wind*.08)),t,.08);}
 stopFlight(){if(!this.flight)return;const f=this.flight;this.flight=null;const t=this.context.currentTime;f.gain.gain.cancelScheduledValues(t);f.gain.gain.setTargetAtTime(.0001,t,.015);f.source.stop(t+.08);}
 impact(points){this.stopFlight();if(!this.enabled)return;if(!points){this.noiseBurst({duration:.17,volume:.18,frequency:550,endFrequency:130,type:'lowpass'});return;}
 // The initial wooden crack, low body punch, and decaying straw rustle form the "baam".
 this.noiseBurst({duration:.055,volume:.62,frequency:4100,endFrequency:1500,type:'lowpass'});
 this.body({frequency:145,endFrequency:48,duration:.3,volume:.8});
 this.body({frequency:310+points*5,endFrequency:145,duration:.15,volume:.2,type:'triangle'});
 this.noiseBurst({duration:.35,volume:.4,frequency:1300,endFrequency:160,type:'lowpass',delay:.008});
 this.noiseBurst({duration:.44,volume:.085,frequency:600,endFrequency:250,q:2,delay:.075});
 }
}
